mapper.update:
UPDATE wrong_question
SET wrong_count = #{wrongCount},
    last_wrong_time = #{lastWrongTime},
    next_review_time = #{nextReviewTime},
    mastered = #{mastered}
WHERE id = #{id}

mapper.select:
SELECT * FROM wrong_question
WHERE user_id = #{userId}
  AND mastered = 0
  AND next_review_time <= #{now}
ORDER BY next_review_time ASC
